Sure, here's an example implementation of the `ShowPostDetails` screen in React Native with TypeScript:
```
typescriptimport React from 'react';
import { View, Text, StyleSheet } from 'react-native';
interface Props {
  route: {
    params: {
      title: string;
      description: string;
    }
  }
}
const ShowPostDetails: React.FC<Props> = ({ route }) => {
  const { title, description } = route.params;
  return (
    <View style={styles.container}>
      <Text style={styles.title}>{title}</Text>
      <Text style={styles.description}>{description}</Text>
    </View>
  );
};
const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 20,
    alignItems: 'center',
    justifyContent: 'center',
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 10,
  },
  description: {
    fontSize: 16,
    lineHeight: 24,
  },
});
export default ShowPostDetails;
```
This screen receives the `title` and `description` as props via the `route.params` object, and displays them in a simple layout with a title and description text.

